function otMin(a,b){if(!a||!b)return 0;let A=a.split(':').map(Number),B=b.split(':').map(Number),m=B[0]*60+B[1]-A[0]*60-A[1];return m<0?m+1440:m}
function otHM(m){m=Math.max(0,Number(m)||0);return Math.floor(m/60)+'時間'+String(m%60).padStart(2,'0')+'分'}
function flowStatus(a){return({DRAFT:'下書き',IN_APPROVAL:'承認中',RETURNED:'差戻し',REJECTED:'却下',APPROVED:'最終承認済',COMPLETED:'処理完了'}[a.status]||a.status)}
function showMyFlowApps(){let rows=flowLoad().apps.filter(a=>a.applicantId===current.id);content.innerHTML=head('自分の申請','時間外勤務申請の進捗を確認します。')+"<div class='card table-wrap'><table><tr><th>申請番号</th><th>勤務日</th><th>申請時間</th><th>状態</th><th></th></tr>"+(rows.map(a=>"<tr><td>"+a.id+"</td><td>"+(a.date||'')+"</td><td>"+otHM(a.minutes||otMin(a.scheduledEnd,a.end))+"</td><td><span class='badge'>"+flowStatus(a)+"</span></td><td><button class='secondary openApp' data-id='"+a.id+"'>開く</button></td></tr>").join('')||"<tr><td colspan='5'>申請はありません。</td></tr>")+"</table></div>";document.querySelectorAll('.openApp').forEach(b=>b.onclick=()=>showFlowDetail(b.dataset.id))}
function flowAction(id,type){let x=flowLoad(),a=x.apps.find(z=>z.id===id),comment=$('#approvalComment')?.value.trim()||'';if((type==='return'||type==='reject')&&!comment)return toast('差戻し・却下には理由を入力してください');if(type==='approve'){a.history.push({at:new Date().toLocaleString('ja-JP'),by:current.name,action:'承認',comment});if(a.currentStep<a.route.length)a.currentStep++;else{a.status='APPROVED';a.approvedAt=new Date().toLocaleString('ja-JP');a.history.push({at:a.approvedAt,by:'システム',action:'最終承認・勤怠処理待ち'})}}else if(type==='return'){a.status='RETURNED';a.history.push({at:new Date().toLocaleString('ja-JP'),by:current.name,action:'差戻し',comment})}else{a.status='REJECTED';a.history.push({at:new Date().toLocaleString('ja-JP'),by:current.name,action:'却下',comment})}flowSave(x);toast(type==='approve'?'承認しました':type==='return'?'差戻しました':'却下しました');showFlowApprovalQueue()}
function showOtProcessing(){let rows=flowLoad().apps.filter(a=>a.status==='APPROVED');content.innerHTML=head('時間外勤務｜勤怠処理待ち','最終承認済み申請を処理完了にします。')+"<div class='card table-wrap'><table><tr><th>申請番号</th><th>職員</th><th>所属</th><th>勤務日</th><th>時間外</th><th></th></tr>"+(rows.map(a=>"<tr><td>"+a.id+"</td><td>"+a.applicant+"</td><td>"+a.dept+"</td><td>"+a.date+"</td><td>"+otHM(a.minutes||otMin(a.scheduledEnd,a.end))+"</td><td><button class='completeOt' data-id='"+a.id+"'>処理完了</button></td></tr>").join('')||"<tr><td colspan='6'>処理待ちはありません。</td></tr>")+"</table></div>";document.querySelectorAll('.completeOt').forEach(b=>b.onclick=()=>{let x=flowLoad(),a=x.apps.find(z=>z.id===b.dataset.id);a.status='COMPLETED';a.completedAt=new Date().toLocaleString('ja-JP');a.history.push({at:a.completedAt,by:current.name,action:'勤怠処理完了'});flowSave(x);toast('処理完了にしました');showOtProcessing()})}
function otPeriod(s){let d=new Date(s+'T00:00:00'),y=d.getFullYear(),m=d.getMonth(),a,b;if(d.getDate()>=11){a=new Date(y,m,11);b=new Date(y,m+1,10)}else{a=new Date(y,m-1,11);b=new Date(y,m,10)}let z=x=>x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');return{start:z(a),end:z(b)}}
function showOtSummary(){let today=new Date().toISOString().slice(0,10);content.innerHTML=head('残業集計','毎月11日～翌月10日で、最終承認済み・処理完了の残業を集計します。')+"<div class='card'><label>集計基準日<input id='sumDate' type='date' value='"+today+"'></label><div id='sumOut'></div></div>";let draw=()=>{let p=otPeriod($('#sumDate').value),rows=flowLoad().apps.filter(a=>['APPROVED','COMPLETED'].includes(a.status)&&a.date>=p.start&&a.date<=p.end),by={};rows.forEach(a=>{let k=a.applicantId||a.applicant;if(!by[k])by[k]={name:a.applicant,dept:a.dept,min:0};by[k].min+=Number(a.minutes||otMin(a.scheduledEnd,a.end))});$('#sumOut').innerHTML="<div class='notice'><b>対象期間：</b>"+p.start+" ～ "+p.end+"</div><table><tr><th>職員</th><th>所属</th><th>合計残業</th></tr>"+(Object.values(by).map(r=>"<tr><td>"+r.name+"</td><td>"+r.dept+"</td><td><b>"+otHM(r.min)+"</b></td></tr>").join('')||"<tr><td colspan='3'>対象データなし</td></tr>")+"</table>"};$('#sumDate').onchange=draw;draw()}
const _buildNav070=buildNav;buildNav=function(){_buildNav070();let bs=[...$('#nav').querySelectorAll('button')],p=bs.find(b=>b.textContent==='処理待ち');if(p)p.onclick=showOtProcessing;if(current.perms.includes('admin')){section('勤怠管理');navBtn('残業集計',showOtSummary,'ot-summary')}};
